\section{Measure associated with a process}

\subsection{Monotone processes}

\begin{definition}\label{def:StieltjesFunction.measure}
  \mathlibok
  \lean{StieltjesFunction.measure}
Let $f : T \to \mathbb{R}$ be a right-continuous monotone function on a conditionally complete linear order $T$.
We denote by $d_+ f$ the measure on $T$ defined by $d_+ f((a, b]) = f(b) - f(a)$ for all $a, b \in T$~.
\end{definition}


\begin{lemma}\label{lem:StieltjesFunction.measurable_measure}
  \uses{def:StieltjesFunction.measure}
Let $X : T \to \Omega \to \mathbb{R}$ be a right-continuous adapted process which is monotone in the time variable.
Then the measure $d_+ X_\omega$ is measurable in $\omega$~.
\end{lemma}

\begin{proof}

\end{proof}



\subsection{Bounded variation processes}


\begin{definition}\label{def:eVariationOn}
  \mathlibok
  \lean{eVariationOn}
The (extended-real-valued) variation of a function $f : T \to E$ on a set $s$ inside a linear order is the supremum of $\sum_i \mathrm{edist}(f(u_{i+1}, f(u_i)))$ over all finite increasing sequences $u : N \to T$ in $s$.
We denote it by $V_f(s)$~.
\end{definition}


\begin{definition}\label{def:BoundedVariationOn}
  \uses{def:eVariationOn}
  \mathlibok
  \lean{BoundedVariationOn}
A function $f : T \to E$ is of bounded variation on a set $s$ if its variation $V_f(s)$ is finite.
\end{definition}


\begin{definition}\label{def:LocallyBoundedVariationOn}
  \uses{def:BoundedVariationOn}
  \mathlibok
  \lean{LocallyBoundedVariationOn}
A function $f : T \to E$ is of locally bounded variation on a set $s$ if for every $a, b$ in $s$, the variation $V_f(s \cap [a, b])$ is finite.
\end{definition}


\begin{definition}\label{def:BoundedVariationOn.vectorMeasure}
  \uses{def:BoundedVariationOn}
  \mathlibok
  %\lean{BoundedVariationOn.vectorMeasure}
Let $f : T \to E$ be a function of bounded variation on a suitable order $T$, with $E$ a complete normed additive group.
Then there exists a signed measure $df$ on $T$ defined by $df((a, b]) = f(b^+) - f(a^+)$~.
\end{definition}


\begin{lemma}\label{lem:BoundedVariationOn.measurable_vectorMeasure}
  \uses{def:BoundedVariationOn.vectorMeasure}
Let $X : T \to \Omega \to E$ be an adapted process which is of bounded variation in the time variable.
Then the measure $dX_\omega$ is measurable in $\omega$~.
\end{lemma}

\begin{proof}

\end{proof}


\begin{lemma}\label{lem:eVariationOn_eq_totalVariation}
  \uses{def:BoundedVariationOn.vectorMeasure, def:eVariationOn}
Denoting by $\vert df \vert$ the total variation of the measure $df$~,
$V_f([a, b]) = \vert df \vert([a, b])$~.
\end{lemma}

\begin{proof}

\end{proof}


\begin{lemma}\label{lem:BoundedVariationOn.vectorMeasure_of_monotone}
  \uses{def:BoundedVariationOn.vectorMeasure, def:StieltjesFunction.measure}
If $f : T \to \mathbb{R}$ is a right-continuous monotone function, then the measure $df$ coincides with the measure $d_+ f$~.
\end{lemma}

\begin{proof}

\end{proof}




\subsection{Integrable processes}

Integrable -> content on the ring of sets generated by predictable rectangles.
Can be extended to a measure on the predictable $\sigma$-algebra if the process is of class DL and ... (see Metivier, Semimartingales, 13.3).

Let $X : T \to \Omega \to E$ be a stochastic process such that $X_t$ is integrable for all $t$~.
For $s < t$ and $A \in \mathcal{F}_s$, let
\begin{align*}
  \mu_X((s, t] \times A) = \mathbb{E}[\mathbf{1}_A (X_t - X_s)]
  \: .
\end{align*}
Set $\mu_X(\{0\} \times A) = 0$~.
Then $\mu_X$ is a content on the predictable rectangles, which can be extended to the ring of sets it generates.

