\subsection{Brownian quadratic variation}

\begin{definition}\label{def:brownianNaturalFiltration}
  \uses{def:brownian}
  \lean{ProbabilityTheory.brownianNaturalFiltration}
The natural filtration of the canonical Brownian motion is
\(\mathcal F^B_t = \sigma(B_s : s \le t)\).
\end{definition}

\begin{lemma}\label{lem:brownianNaturalFiltration_approximable}
  \uses{def:brownianNaturalFiltration}
  \lean{ProbabilityTheory.brownianNaturalFiltration_approximable}
The Brownian natural filtration over the time index \(\mathbb R_{\ge 0}\) is
approximable for the Gaussian limit measure: every stopping time admits a
decreasing sequence of countable-valued stopping times above it that converges
to it almost surely.
\end{lemma}

\begin{proof}
This is the general dyadic approximation of nonnegative-real stopping times.
For a stopping time \(\tau\), set
\[
  \tau_n(\omega)=2^{-n}\lceil 2^n\tau(\omega)\rceil
\]
with the value \(+\infty\) preserved.  Then \(\tau\le \tau_n\), the sequence is
decreasing in \(n\), and \(\tau_n(\omega)\to\tau(\omega)\) for every
\(\omega\).  The range of \(\tau_n\) is countable.  Finally,
\[
  \{\tau_n\le t\}
  =
  \{\tau\le 2^{-n}\lfloor 2^n t\rfloor\},
\]
so \(\tau_n\) is again a stopping time because the right-hand side is measured
at a time not exceeding \(t\).  This gives the required discrete approximation
sequence.
\end{proof}

\begin{lemma}\label{lem:isCadlag_brownian}
  \uses{def:brownian}
  \lean{ProbabilityTheory.isCadlag_brownian}
The canonical Brownian motion has càdlàg paths.
\end{lemma}

\begin{proof}

The canonical Brownian paths are continuous, and every continuous path is càdlàg.
\end{proof}

\begin{lemma}\label{lem:martingale_brownian}
  \uses{def:brownianNaturalFiltration}
  \lean{ProbabilityTheory.martingale_brownian}
The canonical Brownian motion is a martingale with respect to its natural filtration.
\end{lemma}

\begin{proof}

The Brownian motion is a filtered pre-Brownian motion for its natural filtration:
it is adapted by definition of the natural filtration, and each future increment
\(B_t-B_s\), \(s\le t\), is independent of \(\mathcal F^B_s\).  The increment is
centered, so
\[
  \mathbb E[B_t-B_s\mid \mathcal F^B_s]=0.
\]
Since \(B_s\) is \(\mathcal F^B_s\)-measurable,
\[
  \mathbb E[B_t\mid\mathcal F^B_s]
  =\mathbb E[B_t-B_s\mid\mathcal F^B_s]+B_s
  =B_s.
\]
\end{proof}

\begin{lemma}\label{lem:isLocalMartingale_brownian}
  \uses{lem:martingale_brownian, lem:isCadlag_brownian, def:IsLocalMartingale}
  \lean{ProbabilityTheory.isLocalMartingale_brownian}
The canonical Brownian motion is a local martingale with respect to its natural filtration.
\end{lemma}

\begin{proof}

Every càdlàg martingale is a local martingale, applied to
Lemmas~\ref{lem:martingale_brownian} and \ref{lem:isCadlag_brownian}.
\end{proof}

\begin{definition}\label{def:brownianQuadraticVariation}
  \uses{def:quadraticVariation, lem:isLocalMartingale_brownian, lem:isCadlag_brownian, lem:brownianNaturalFiltration_approximable}
  \lean{ProbabilityTheory.brownianQuadraticVariation}
The quadratic variation process attached to the canonical Brownian motion is
\[
  \langle B\rangle := \operatorname{quadraticVariation}(B).
\]
Formally this is an application of the generic quadratic-variation definition,
so the Brownian filtration must satisfy the usual hypotheses required by the
normalized Doob--Meyer choice layer.  Approximability is supplied by
Lemma~\ref{lem:brownianNaturalFiltration_approximable}; completeness and
right-continuity are genuine usual-condition obligations for the filtration
used in the formal statement, not consequences to assert for the raw natural
filtration without proof.
\end{definition}

\begin{lemma}\label{lem:martingale_brownian_sq_sub_time}
  \uses{def:brownianNaturalFiltration}
  \lean{ProbabilityTheory.martingale_brownian_sq_sub_time}
The process \(B_t^2-t\) is a martingale with respect to the natural Brownian filtration.
\end{lemma}

\begin{proof}

It is adapted because \(B_t\) is \(\mathcal F^B_t\)-measurable and \(t\) is
deterministic.  It is integrable because \(B_t\) is Gaussian with finite second
moment.

Fix \(s\le t\) and write \(\Delta_{s,t}=B_t-B_s\).  Then
\[
  B_t^2-t
  = B_s^2-s + 2B_s\Delta_{s,t}
    +\bigl(\Delta_{s,t}^2-(t-s)\bigr).
\]
The increment \(\Delta_{s,t}\) is independent of \(\mathcal F^B_s\), centered,
and has law \(N(0,t-s)\).  Therefore
\[
  \mathbb E[\Delta_{s,t}\mid\mathcal F^B_s]=0,
  \qquad
  \mathbb E[\Delta_{s,t}^2\mid\mathcal F^B_s]=t-s.
\]
Since \(B_s\) is \(\mathcal F^B_s\)-measurable, the mixed term has conditional
expectation
\[
  \mathbb E[B_s\Delta_{s,t}\mid\mathcal F^B_s]
  = B_s\,\mathbb E[\Delta_{s,t}\mid\mathcal F^B_s]=0.
\]
Taking conditional expectations in the displayed expansion gives
\[
  \mathbb E[B_t^2-t\mid\mathcal F^B_s]=B_s^2-s,
\]
which is the martingale property.
\end{proof}

\begin{lemma}\label{lem:quadraticVariation_brownian}
  \uses{def:brownianQuadraticVariation, lem:martingale_brownian_sq_sub_time, lem:predictablePart_eq_of_normalized_decomposition}
  \lean{ProbabilityTheory.quadraticVariation_brownian}
Let \(B\) be the canonical Brownian motion. Then its quadratic variation is
given by \(\langle B \rangle_t = t\).
\end{lemma}

\begin{proof}
The candidate Doob--Meyer decomposition of \(B_t^2\) is
\[
  B_t^2 = (B_t^2-t) + t.
\]
By Lemma~\ref{lem:martingale_brownian_sq_sub_time}, the first summand is a
local martingale.  The second summand is deterministic, càdlàg, predictable,
locally integrable, nondecreasing, and starts from zero.  A normalized
Doob--Meyer uniqueness theorem therefore identifies the predictable part of
\(B_t^2\) with \(t\).

In the current Lean route this last step must use a predictable-part
identification theorem for normalized Doob--Meyer decompositions.  Without the
normalization \(A_0=0\), the predictable part is not unique: one can shift a
constant between the martingale and finite-variation parts.  Thus the equality
\(\langle B\rangle_t=t\) should not be formalized from the present
choice-based \texttt{predictablePart} API until that uniqueness/normalization input is
available.
\end{proof}

